svg:

    .container {
position: relative;
width: 100%;
height: 220px;
overflow: hidden;
display: flex;
flex-direction: column;
align-items: center;
justify-content: center;
font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif;
}
.title {
font-size: 48px;
font-weight: 800;
background: linear-gradient(90deg, #a855f7, #ec4899, #f43f5e);
-webkit-background-clip: text;
-webkit-text-fill-color: transparent;
margin: 0;
z-index: 2;
}
.subtitle {
font-size: 18px;
color: #c084fc;
margin-top: 8px;
font-weight: 500;
z-index: 2;
}
@keyframes fall {
0% { transform: translateY(-30px) translateX(0px) rotate(0deg); opacity: 0; }
15% { opacity: 0.9; }
85% { opacity: 0.9; }
100% { transform: translateY(240px) translateX(45px) rotate(360deg); opacity: 0; }
}
.petal {
position: absolute;
top: -20px;
width: 14px;
height: 14px;
background: radial-gradient(circle at 30% 30%, #ffd1dc, #ff8da1);
border-radius: 150% 0 150% 0;
animation: fall linear infinite;
z-index: 1;
}
.p1 { left: 8%; animation-duration: 5s; animation-delay: 0s; width: 12px; height: 12px; }
.p2 { left: 20%; animation-duration: 7s; animation-delay: 1.5s; }
.p3 { left: 34%; animation-duration: 4.5s; animation-delay: 0.8s; width: 10px; height: 10px; }
.p4 { left: 48%; animation-duration: 6.5s; animation-delay: 2.2s; }
.p5 { left: 62%; animation-duration: 5.5s; animation-delay: 0.4s; width: 16px; height: 16px; }
.p6 { left: 75%; animation-duration: 7.2s; animation-delay: 1.8s; }
.p7 { left: 88%; animation-duration: 4.8s; animation-delay: 2.8s; width: 11px; height: 11px; }
.p8 { left: 94%; animation-duration: 6s; animation-delay: 1s; }
